import{_ as i,l as c,o as a,c as d,v as t,p as o,x as s,d as l,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"sched_ext 与 BPF 调度器","description":"","frontmatter":{"title":"sched_ext 与 BPF 调度器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sched-ext.md","filePath":"cs/sched-ext.md","lastUpdated":1789023840000}'),n={name:"cs/sched-ext.md"};function B(_,e,P,u,x,E){const r=c("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="sched-ext-与-bpf-调度器" tabindex="-1">sched_ext 与 BPF 调度器 <a class="header-anchor" href="#sched-ext-与-bpf-调度器" aria-label="Permalink to &quot;sched_ext 与 BPF 调度器&quot;">​</a></h1><div class="epigraph"><p>sched_ext 把调度类的入队、选下一个、时间片交给 BPF 程序，使自定义策略不必改内核 C 代码。</p><footer>—— 据 Linux sched_ext 文档；eBPF 验证器约束；[XDP](/cs/xdp-ebpf) 为可编程数据面先修</footer></div><p><a href="/cs/cgroup-cpu-sched">cgroup CPU</a> 仍是固定算法。<a href="/cs/xdp-ebpf">eBPF</a> 已在网络早路径出现。缺口是 <strong>把调度策略变成可加载 BPF</strong>：SCX。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据中心想按作业类型选核，主线 CFS 不够。sched_ext：新调度类，回调 <code>enqueue</code>/<code>dispatch</code> 在 BPF 中。缺口：verifier 保证不能死循环太久；错误程序踢回 CFS；与 RT/DL 的优先级关系。本课不把每个示例调度器（scx_simple）当产品。</p><p><span class="marginnote">仍在内核态跑 BPF，不是用户态 M:N。失败安全是硬要求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载 scx 程序 → 任务可选 SCX 策略 → BPF 维护自己的队列（map）。对照 XDP：一个选包命运，一个选任务。对照 <a href="/cs/fuse">FUSE</a>：FUSE 出核；SCX 仍在核内 JIT。对照 EEVDF：可在 BPF 里实现别的公平。</p>',8)),(a(),o(h,null,{default:s(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENQ%5B%22%E4%BB%BB%E5%8A%A1%E5%85%A5%E9%98%9F%22%5D%20--%3E%20BPF%5B%22BPF%20enqueue%22%5D%0A%20%20TICK%5B%22%E9%9C%80%E8%A6%81%E4%B8%8B%E4%B8%80%E4%B8%AA%22%5D%20--%3E%20DISP%5B%22BPF%20dispatch%22%5D%0A%20%20BAD%5B%22verifier%20%E6%88%96%E8%BF%90%E8%A1%8C%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20CFS%5B%22%E5%9B%9E%E9%80%80%E9%BB%98%E8%AE%A4%E7%B1%BB%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>sched_ext 把调度器从编译进内核的算法变成可热更新策略，同时用 verifier 限制危害。它不自动正确。不要写成 AI 调度器营销。与 <a href="/cs/preempt-rt">PREEMPT_RT</a>：RT 路径通常不交给随意 BPF。</p><p>调试：BPF 统计 map；错误会导致抖动回退。</p><p>实现上：BPF 调度器崩溃或 verifier 失败必须回退，否则机器不可调度。map 里自己维护的队列要处理迁移和热插 CPU。与 RT 类的优先级关系由内核固定。 读法上只引用<a href="/cs/cgroup-cpu-sched">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>sched_ext 与 BPF 调度器</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 kfunc。不保证稳定 ABI。下一课用户态 M:N：协程调度与内核线程的关系。</p><p>版本字段会变，课序钉的是机制对象「sched_ext 与 BPF 调度器」，不是某一主线内核的结构体名。 后课默认：公平类策略可 BPF 化。用户态调度与 M:N，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>sched_ext 用 BPF 实现调度回调。</li><li>失败回退；verifier 限制程序。</li><li>用户态调度是下一课。</li><li>出处：Linux sched_ext；eBPF；XDP 对照。</li></ul>',11))])}const m=i(n,[["render",B]]);export{F as __pageData,m as default};
